          "contextPassage": "【中文 1：利他行動の進化と共感のメカニズム】\n\n人間はなぜ、自らの利益を犠牲にしてまで他者を助ける「利他行動」をとるのだろうか。古典的な進化論の視点に立てば、自らの生存と生殖の確率を最大化することが個体の目的であるはずだ。したがって、自分に直接の見返りがない行動は淘汰されるはずである。しかし現実には、見知らぬ他人に席を譲ったり、災害時に危険を冒して救助活動に参加したりする光景は世界中で見られる。\n\n近年の進化生物学や脳科学の研究は、この謎に対して新たな光を当てている。人間は過酷な自然環境を生き抜くために、強固な集団（コミュニティ）を形成し、互いに協力し合う能力を進化させてきた。集団全体の生存確率が高まることが、結果としてその構成員である個人の生存にも寄与したのである。\n\nさらに、脳内には他者の痛みや喜びを自分のことのように追体験する「ミラーニューロン」をはじめとする共感システムが備わっていることが分かってきた。他者を助けることで得られる「温かい感情」や誇りは、脳内の報酬系を活性化させる。つまり、利他行動とは単なる道徳的な義務感から生じるものではなく、人間の生存戦略として遺伝子レベルで組み込まれた、生物学的に自然な欲求なのである。",
