          "stem": "従来の製品開発において生じていた問題点は何か。",
          "stimulusId": "N2-MED-03",
          "contextPassage": "【中文 3：デザインにおける「引き算の美学」】\n\n多くの製品開発現場では、競合他社との差別化を図るために「機能の追加」が繰り返される。ボタンの数を増やし、あらゆる用途に対応できる多機能性をアピールすることが、顧客への価値提供だと信じられているからだ。しかしその結果、取扱説明書を読まなければ基本操作すらできない、複雑で扱いにくい製品が市場に溢れかえることになった。\n\nこれに対して、近年世界中で支持を集めているのが「引き算の美学」である。これは、製品が果たすべき本質的な目的を徹底的に突き詰め、それ以外の余分な要素を極限まで削ぎ落とす設計思想を指す。要素を減らすことは、一見すると妥協や手抜きのように思えるかもしれないが、実際には足し算よりもはるかに高度な判断力と技術が要求される。\n\n何かを削るためには、「何が本当に不可欠なのか」を完璧に理解していなければならない。無駄のない洗練された造形は、ユーザーに直感的な操作を可能にさせ、美的な感動を与える。真に優れたデザインとは、これ以上付け足すものがない状態ではなく、これ以上削るものがない極限の調和に宿るのである。",
